export const levels={
 basic:{label:'Inicial',pool:['pressure','jamA','i1'],hints:3,description:'Tres causas en A, punto de fallo fijo y hasta 3 pistas.'},
 intermediate:{label:'Intermedio',pool:['pressure','jamA','jamB','i1','i3'],hints:2,description:'Cinco causas en A o B y hasta 2 pistas.'},
 expert:{label:'Avanzado',pool:['pressure','jamA','jamB','i1','i3'],hints:3,description:'Dos fallos simultáneos: presión o atasco junto a sensor desconectado. Dos etapas de diagnóstico, hasta 3 pistas y punto de fallo variable.'}
};
const KEY='mecanica-diagnostic-history-v1';
export let historyVersion=0;
let fallback=[],storageFailed=false;
export function scoreDiagnostic(d){return d.solved?Math.max(0,100-20*(d.errors??Math.max(0,d.attempts-1))-10*d.hints):0;}
export function readHistory(storage){try{const target=storage===undefined?globalThis.localStorage:storage;if(!target)throw Error('storage unavailable');const raw=target.getItem(KEY);if(!raw)return fallback;const rows=JSON.parse(raw);if(!Array.isArray(rows))return fallback;return rows.filter(r=>r&&typeof r.id==='string'&&levels[r.level]&&['solved','revealed','abandoned'].includes(r.outcome)&&Number.isFinite(r.score)&&r.score>=0&&r.score<=100&&Number.isInteger(r.attempts)&&r.attempts>=0&&Number.isInteger(r.hints)&&r.hints>=0&&Number.isFinite(r.date)).slice(-100);}catch{storageFailed=true;return fallback;}}
export function saveDiagnostic(d,storage){if(!d||d.recorded)return;const rows=readHistory(storage);const entry={id:d.runId||String(Date.now())+Math.random(),level:d.level||'intermediate',faultCount:d.ids?.length||1,identified:d.confirmed?.length||0,outcome:d.solved?'solved':d.revealed?'revealed':'abandoned',score:scoreDiagnostic(d),attempts:d.attempts,hints:d.hints,date:Date.now()};if(!rows.some(r=>r.id===entry.id))rows.push(entry);fallback=rows.slice(-100);try{const target=storage===undefined?globalThis.localStorage:storage;if(!target)throw Error('storage unavailable');target.setItem(KEY,JSON.stringify(fallback));storageFailed=false;}catch{storageFailed=true;}d.recorded=true;historyVersion++;}
export function historyStorageFailed(){return storageFailed;}
export function summarizeHistory(rows,level){const all=rows.filter(r=>r.level===level),finished=all.filter(r=>r.outcome!=='abandoned'),recent=finished.slice(-5),previous=finished.slice(-10,-5),mean=a=>a.length?a.reduce((sum,r)=>sum+r.score,0)/a.length:null;return {total:all.length,solved:all.filter(r=>r.outcome==='solved').length,abandoned:all.filter(r=>r.outcome==='abandoned').length,best:finished.length?Math.max(...finished.map(r=>r.score)):null,recent:mean(recent),previous:mean(previous),recentCount:recent.length,previousCount:previous.length};}
